-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromePool.json. Do not edit: change the chain file or ABI and regenerate.
-- Sync(uint256,uint256)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_pool__sync',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    reinterpretAsUInt256(reverse(unhex(substring(data, 3, 64)))) as reserve0,
    reinterpretAsUInt256(reverse(unhex(substring(data, 67, 64)))) as reserve1
from {{ source('chain_base', 'logs') }}
where topic0 = '0xcf2aa50876cdfbb541206f89af0ee78d44a2abf8d328e37fa4917f982149848a'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_pool')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
